def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]

    if v1 == 0:
        return {"value": None, "trace": {"output_meta": {"currency": None, "scale": None, "unit": "percent"}}}

    change_ratio = (v2 - v1) / v1 * 100
    return {
        "value": change_ratio,
        "trace": {
            "change": v2 - v1,
            "base_2018": v1,
            "output_meta": {"currency": None, "scale": None, "unit": "percent"},
        },
    }
